import * as React from "react";
import { Alert, Box, IconButton, Paper, Snackbar, Tooltip, Typography, Stack } from "@mui/material";
import SchoolIcon from '@mui/icons-material/School';
import { PublicProfileResult } from "@/types/profile.types";
import PlaceIcon from '@mui/icons-material/Place';
import WorkIcon from '@mui/icons-material/Work';
import LocalLibraryIcon from '@mui/icons-material/LocalLibrary';
import { ProfileType, Roles } from "@/types/api.types";
import PersonIcon from '@mui/icons-material/Person';
import EmailIcon from '@mui/icons-material/Email';
import PhoneIcon from '@mui/icons-material/Phone';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import ShareIcon from '@mui/icons-material/Share';
import SecurityIcon from '@mui/icons-material/Security';
import { ProfileInfoDialog } from '@/components/ProfileInfoDialog';
import { VerifiedBadge } from '@/components/ui';

/** Strip everything except digits; preserves a leading '+' for tel: links. */
const toDialableNumber = (raw: string): string => {
  const trimmed = raw.trim();
  const plus = trimmed.startsWith('+') ? '+' : '';
  return plus + trimmed.replace(/[^0-9]/g, '');
};

/** wa.me requires digits only — no '+', spaces, or punctuation. */
const toWhatsAppDigits = (raw: string): string => raw.replace(/[^0-9]/g, '');

/** Compact icon + text row */
const InfoRow: React.FC<{ icon: React.ReactNode; children: React.ReactNode }> = ({ icon, children }) => (
  <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 0.75, minWidth: 0, py: 0.2 }}>
    <Box sx={{ color: 'action.active', display: 'flex', flexShrink: 0, mt: '2px' }}>{icon}</Box>
    <Typography variant="body2" sx={{ fontSize: '0.8125rem', wordBreak: 'break-word' }}>
      {children}
    </Typography>
  </Box>
);

const getProfileBadgeText = (profile: PublicProfileResult): string => {
  const entry = profile.entryYear > 0 ? `${profile.entryYear}` : '';
  const exit = profile.exitYear > 0 ? `${profile.exitYear}` : '';

  switch (profile.profileType) {
    case ProfileType.Alumni: 
      if (entry && exit) return `${entry}–${exit}`;
      if (!entry && exit) return `?–${exit}`;
      return entry || '';
    case ProfileType.Student: 
      if (entry) return `${entry}–Present`;
      if (exit) return `?–${exit}`;
      return '';
    case ProfileType.Staff: 
      if (entry) return `${entry}–Present`;
      return '';
    case ProfileType.ExStaff: 
      if (entry && exit) return `${entry}–${exit}`;
      if (!entry && exit) return `?–${exit}`;
      return entry || '';
    default: return '';
  }
};

interface PersonDisplayProps extends PublicProfileResult {
  isAdmin?: boolean;
  footer?: React.ReactNode;
  /** Extra content rendered inside the card body, just below the info grid. */
  extra?: React.ReactNode;
  /** Hide location, employment and higher-education info rows (e.g. for admin role management). */
  minimal?: boolean;
  /** Roles to display when already available (no extra fetch). Shown only when non-empty. */
  roles?: Roles[];
}

export const PersonDisplay: React.FunctionComponent<PersonDisplayProps> = (props) => {
  const { isAdmin, footer, extra, minimal, roles, ...profile } = props;
  const [detailOpen, setDetailOpen] = React.useState(false);
  const [shareNotice, setShareNotice] = React.useState<{ severity: 'success' | 'error'; text: string } | null>(null);

  // The backend (ProfileAccessPolicy) is the only authority on what's
  // populated in the response. The UI just renders whatever made it through —
  // no per-field role / owner-flag gating here.
  const canOpenDialog = !!isAdmin;
  const showLocation  = !minimal && !!profile.location;
  const showPhone     = !!profile.phone;
  const showEmail     = !!profile.email;
  const showEmployment = !minimal && (!!profile.jobTitle || !!profile.organisation);
  const showEducation  = !minimal && (!!profile.degree   || !!profile.university);

  const employmentText = [profile.jobTitle, profile.organisation].filter(Boolean).join(' at ');
  const educationText  = [profile.degree,   profile.university ].filter(Boolean).join(', ');

  const jnvText        = [profile.firstJnvName, profile.otherJnvNames].filter(Boolean).join(', ');
  const inlineLocation = minimal && profile.location ? profile.location : '';
  const jnvAndLocation = [jnvText, inlineLocation].filter(Boolean).join(' · ');

  const elevatedRoles = roles?.filter(r => r !== Roles.User) ?? [];

  const chipLabel = (() => {
    const type  = profile.profileType;
    const badge = getProfileBadgeText(profile);
    const batch = profile.batch && profile.batch > 0 ? `Batch · ${profile.batch}` : '';
    const head  = type && badge ? `${type} · ${badge}` : (type || '');
    if (head && batch) return `${head} | ${batch}`;
    return head || batch || '';
  })();

  const shareUrl = `${window.location.origin}/profile/${profile.id}`;
  const shareTitle = profile.name || 'Alumni profile';

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({ title: shareTitle, text: shareTitle, url: shareUrl });
        return;
      } catch {
        return; // user dismissed the share sheet
      }
    }
    try {
      await navigator.clipboard.writeText(shareUrl);
      setShareNotice({ severity: 'success', text: 'Profile link copied to clipboard' });
    } catch {
      setShareNotice({ severity: 'error', text: 'Unable to share on this device' });
    }
  };

  return (
    <Paper
      elevation={1}
      sx={{
        p: 1.5,
        mb: 1,
        borderRadius: 2,
        borderLeft: 3,
        borderColor: 'primary.light',
        transition: 'box-shadow 0.2s ease',
        '&:hover': { boxShadow: 4 },
      }}
    >
      {/* Header: Name + Badge. Mobile stacks the pill below the name. */}
      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={{ xs: 0.5, sm: 1 }}
        sx={{
          alignItems: { xs: 'flex-start', sm: 'center' },
          justifyContent: 'space-between',
          mb: 0.5,
        }}
      >
        <Stack direction="row" spacing={0.75} sx={{ alignItems: 'center', minWidth: 0 }}>
          <PersonIcon sx={{ fontSize: '1.1rem', color: 'primary.main' }} />
          <Typography
            variant="subtitle2"
            onClick={canOpenDialog ? () => setDetailOpen(true) : undefined}
            sx={{ fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', ...(canOpenDialog && { cursor: 'pointer', '&:hover': { textDecoration: 'underline' } }) }}
          >
            {profile.name}
          </Typography>
          <VerifiedBadge verified={profile.isVerified} iconOnly />
        </Stack>
        {chipLabel && (
          <Box
            sx={{
              flexShrink: 0,
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '0.7rem',
              fontWeight: 500,
              lineHeight: 1.4,
              px: 0.75,
              py: 0.25,
              borderRadius: 0.5,
              bgcolor: 'action.hover',
              color: 'text.secondary',
              whiteSpace: 'nowrap',
              textAlign: 'center',
            }}
          >
            {chipLabel}
          </Box>
        )}
      </Stack>

      {/* Info grid: 2-column on desktop, 1-column on mobile */}
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' }, gap: 0.25, ml: 0.25 }}>
        {jnvAndLocation && (
          <InfoRow icon={<LocalLibraryIcon sx={{ fontSize: '0.95rem' }} />}>
            {jnvAndLocation}
          </InfoRow>
        )}
        {showLocation && (
          <InfoRow icon={<PlaceIcon sx={{ fontSize: '0.95rem' }} />}>
            {profile.location}
          </InfoRow>
        )}
        {showPhone && (
          <InfoRow icon={<PhoneIcon sx={{ fontSize: '0.95rem' }} />}>
            {profile.phone}
          </InfoRow>
        )}
        {showEmail && (
          <InfoRow icon={<EmailIcon sx={{ fontSize: '0.95rem' }} />}>
            {profile.email}
          </InfoRow>
        )}
        {showEmployment && (
          <InfoRow icon={<WorkIcon sx={{ fontSize: '0.95rem' }} />}>
            {employmentText}
          </InfoRow>
        )}
        {showEducation && (
          <InfoRow icon={<SchoolIcon sx={{ fontSize: '0.95rem' }} />}>
            {educationText}
          </InfoRow>
        )}
        {elevatedRoles.length > 0 && (
          <InfoRow icon={<SecurityIcon sx={{ fontSize: '0.95rem' }} />}>
            {elevatedRoles.join(', ')}
          </InfoRow>
        )}
      </Box>

      {extra && (
        <Box sx={{ mt: 0.75, ml: 0.25 }}>
          {extra}
        </Box>
      )}

      <Stack direction="row" spacing={2} sx={{ mt: 0.75, justifyContent: 'flex-end', alignItems: 'center' }}>
        {showPhone && (
          <>
            <Tooltip title="Call">
              <IconButton
                size="small"
                component="a"
                href={`tel:${toDialableNumber(profile.phone!)}`}
                aria-label="Call"
                sx={{
                  p: 0.5,
                  color: 'primary.main',
                  '&:hover': { bgcolor: 'action.hover' },
                }}
              >
                <PhoneIcon sx={{ fontSize: '1.1rem' }} />
              </IconButton>
            </Tooltip>
            <Tooltip title="Message on WhatsApp">
              <IconButton
                size="small"
                component="a"
                href={`https://wa.me/${toWhatsAppDigits(profile.phone!)}`}
                target="_blank"
                rel="noopener noreferrer"
                aria-label="WhatsApp"
                sx={{
                  p: 0.5,
                  color: 'success.main',
                  '&:hover': { bgcolor: 'action.hover' },
                }}
              >
                <WhatsAppIcon sx={{ fontSize: '1.1rem' }} />
              </IconButton>
            </Tooltip>
          </>
        )}
        <Tooltip title="Share profile">
          <IconButton
            size="small"
            onClick={handleShare}
            aria-label="Share profile"
            sx={{
              p: 0.5,
              color: 'text.secondary',
              '&:hover': { bgcolor: 'action.hover' },
            }}
          >
            <ShareIcon sx={{ fontSize: '1.1rem' }} />
          </IconButton>
        </Tooltip>
      </Stack>

      {footer && (
        <Box sx={{ mt: 1, pt: 1, borderTop: '1px solid', borderColor: 'divider' }}>
          {footer}
        </Box>
      )}

      {canOpenDialog && (
        <ProfileInfoDialog
          open={detailOpen}
          profileId={profile.id}
          onClose={() => setDetailOpen(false)}
        />
      )}

      <Snackbar
        open={!!shareNotice}
        autoHideDuration={3000}
        onClose={() => setShareNotice(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert
          severity={shareNotice?.severity ?? 'success'}
          variant="outlined"
          onClose={() => setShareNotice(null)}
          sx={{ width: '100%', bgcolor: '#f5f5f5', borderWidth: 2, boxShadow: 6 }}
        >
          {shareNotice?.text}
        </Alert>
      </Snackbar>
    </Paper>
  );
};